# Batch 01: general car-maintenance Q&A (petrol/diesel/hybrid/EV basics).
# Each topic id is used as `source_id` so train/val/test are split by topic (no leakage).
# Format: "topic_id": ("Topic title", [(question, answer), ...])

DATA = {
"engine_oil_basics": ("Engine oil basics", [
 ("What does engine oil do?", "Engine oil lubricates moving parts, reduces friction and wear, helps carry heat away from the engine, and holds dirt and combustion by-products in suspension until the oil is drained."),
 ("Why does engine oil turn dark?", "Oil darkens as it picks up soot and contaminants, which is normal. Judge it by distance and time since the last change and by its condition: gritty, milky or fuel-smelling oil is a warning sign."),
 ("How do I check the engine oil level?", "Park on level ground with the engine off for a few minutes. Pull the dipstick, wipe it, reinsert it fully, pull it out again and check that the level is between the min and max marks."),
 ("Can I mix different brands of engine oil?", "In an emergency top-up it is usually acceptable if the viscosity grade and specification match. For regular use, stick to the grade and specification in the owner's manual."),
]),
"oil_change_intervals": ("Oil change intervals", [
 ("How often should I change my engine oil?", "Follow the owner's manual. Typical intervals are 5,000-10,000 km or 6-12 months, whichever comes first, with the shorter end for severe use."),
 ("Does oil need changing if the car is barely driven?", "Yes. Oil degrades with time through oxidation and moisture even when mileage is low, so change it by the time interval too."),
 ("Can synthetic oil go longer between changes than mineral oil?", "Synthetic oil usually resists breakdown better and often allows longer intervals, but only extend the interval if the manufacturer's schedule permits it."),
 ("What counts as severe driving for oil changes?", "Frequent short trips, stop-and-go traffic, dusty roads, towing and extreme heat all wear oil out faster, so use the shorter interval."),
]),
"oil_viscosity": ("Oil viscosity and grades", [
 ("What does 5W-30 mean?", "The first number with W (winter) shows how easily the oil flows when cold; lower flows more easily. The second number shows its thickness at normal operating temperature."),
 ("Can I use a thicker oil in an older engine?", "Only if the manufacturer allows it. The wrong viscosity can reduce protection or fuel efficiency, so check the owner's manual first."),
 ("Where can I find the oil grade my car needs?", "In the owner's manual. Many engines also print the recommended viscosity on the oil filler cap."),
 ("What do API and ACEA ratings on oil mean?", "They are quality and performance standards for oils. Use the specification your manual lists, not just the right viscosity."),
]),
"oil_filter": ("Oil filter", [
 ("Should I replace the oil filter at every oil change?", "Normally yes. An old filter holds dirty oil and can clog, which defeats the purpose of fresh oil."),
 ("What problems can a clogged oil filter cause?", "A clogged filter can restrict oil flow, which may trigger the low oil pressure warning or increase engine noise, though other faults can cause the same signs."),
 ("How tight should a new oil filter be?", "Follow the instructions on the filter. It is commonly hand-tight, about three-quarters of a turn after the gasket touches the engine. Do not use a wrench to over-tighten it."),
 ("Why put oil on the new filter's gasket?", "A thin film of fresh oil helps the gasket seal and stops it tearing or sticking when the filter is tightened."),
]),
"coolant": ("Engine coolant", [
 ("What does coolant do?", "Coolant carries heat from the engine to the radiator, raises the boiling point, prevents freezing and protects the cooling system from corrosion."),
 ("Can I use plain water instead of coolant?", "Only as a short-term emergency measure. Water lacks corrosion protection and boils at a lower temperature, so go back to the recommended coolant mix, usually concentrate and distilled water."),
 ("How often should coolant be replaced?", "Follow the manual. Many cars need it every 2-5 years or at a set distance, depending on the coolant type."),
 ("Can I mix coolants of different colours?", "Do not rely on colour to judge compatibility. Mixing incompatible types can form gel or reduce protection, so use the type your manual specifies."),
]),
"overheating": ("Engine overheating", [
 ("What should I do if the temperature gauge climbs into the red?", "Switch off the AC, turn the heater to full to pull heat out of the engine, pull over safely and switch off the engine. Let it cool before checking anything."),
 ("Is it safe to open the radiator cap on a hot engine?", "No. The system is under pressure and hot coolant can spray out and cause serious burns. Wait until the engine is completely cool."),
 ("What are common causes of overheating?", "Low coolant or a leak, a stuck thermostat, a failing water pump, a clogged radiator, a broken cooling fan, or a blown head gasket."),
 ("Can I keep driving a car that is overheating?", "No. Continuing can warp the cylinder head or blow the head gasket, which is very expensive to repair."),
]),
"battery_care": ("Battery care", [
 ("How long does a car battery usually last?", "Commonly around 3-5 years, depending on climate, usage and quality. Heat shortens battery life."),
 ("What are signs of a weak car battery?", "Slow cranking, dim lights at idle, a clicking sound when starting, the battery warning light, or a swollen battery case."),
 ("How do I clean corroded battery terminals?", "With the engine off, disconnect the negative terminal first, clean the corrosion with a baking soda and water mix and a brush, dry it, then reconnect the negative terminal last."),
 ("Do short trips hurt the battery?", "Yes. Short trips often do not give the alternator enough time to recharge the energy used for starting, so the battery gradually weakens."),
]),
"jump_start": ("Jump-starting", [
 ("How do I jump-start a car safely?", "Connect red to the dead battery's positive, the other red to the donor's positive, black to the donor's negative, and the last black clamp to unpainted metal on the dead car's engine away from the battery. Start the donor, then the dead car, and remove the clamps in reverse order."),
 ("Why not connect the last clamp to the dead battery's negative terminal?", "Connecting it there can create a spark near the battery, which may give off flammable hydrogen gas. A bare metal ground point is safer."),
 ("What should I do after a jump start?", "Drive for at least 20-30 minutes, or get the battery tested. It may be failing or the alternator may not be charging."),
 ("Can jump-starting damage a modern car?", "Wrong polarity or voltage spikes can damage electronics. Check the owner's manual, since some cars specify dedicated jump-start points."),
]),
"tyre_pressure": ("Tyre pressure", [
 ("Where do I find the correct tyre pressure for my car?", "On the placard in the driver's door jamb, in the owner's manual, or sometimes inside the fuel flap. The number on the tyre sidewall is the tyre's maximum, not the recommended pressure."),
 ("When should I check tyre pressure?", "At least monthly and before long trips, with the tyres cold, meaning the car has not been driven far."),
 ("What happens if tyres are under- or over-inflated?", "Under-inflation causes edge wear, extra heat, worse mileage and weaker handling. Over-inflation causes centre wear, a harsher ride and less grip."),
 ("Does temperature change tyre pressure?", "Yes, roughly 1 psi for every 10 degrees F (about 5-6 degrees C) change, so pressure drops in cold weather."),
]),
"tyre_rotation_alignment": ("Tyre rotation and alignment", [
 ("How often should I rotate my tyres?", "Commonly every 8,000-10,000 km or as the manual says. Rotation evens out wear across all four tyres."),
 ("What are signs of bad wheel alignment?", "The car pulls to one side, the steering wheel sits off-centre when driving straight, or the tyres wear unevenly."),
 ("What is the difference between wheel alignment and balancing?", "Alignment sets the angles of the wheels relative to the car. Balancing corrects uneven weight distribution in the wheel and tyre to stop vibration."),
 ("Can hitting a pothole affect my car?", "Yes. It can knock the alignment out and damage the tyre, rim or suspension. Get it checked if the car pulls or vibrates afterwards."),
]),
"tyre_tread_age": ("Tyre tread and age", [
 ("What is the minimum legal tyre tread depth?", "In many countries it is 1.6 mm, but check local rules. Many experts suggest replacing tyres around 3 mm for better wet grip."),
 ("How can I check my tyre tread?", "Use a tread depth gauge or look at the tread wear indicator bars in the grooves. When the tread is level with them, the tyre is due for replacement."),
 ("Do tyres expire even if the tread looks fine?", "Rubber hardens and degrades with age. Many manufacturers advise regular inspection after about 5 years and replacement at around 10 years regardless of tread."),
 ("How do I read the manufacture date on a tyre?", "Look for the DOT code on the sidewall. The last four digits give the week and year, so 2323 means the 23rd week of 2023."),
]),
"brake_pads": ("Brake pads", [
 ("What are the signs of worn brake pads?", "Squealing from the wear indicator, grinding noises, longer stopping distances, vibration when braking, or a brake warning light."),
 ("How long do brake pads usually last?", "It varies widely, often 30,000-70,000 km depending on driving style, traffic and pad type."),
 ("Can I replace the pads on just one wheel?", "No. Pads should be replaced in pairs on the same axle so braking stays even."),
 ("What happens if I ignore grinding brakes?", "The pads wear down to metal and damage the discs, which costs more to fix and reduces braking safety."),
]),
"brake_fluid": ("Brake fluid", [
 ("Why does brake fluid need to be changed?", "Brake fluid absorbs moisture over time. That lowers its boiling point and can corrode parts, leading to a spongy pedal or reduced braking."),
 ("How often should brake fluid be replaced?", "Commonly about every 2 years, or as the owner's manual specifies."),
 ("What causes a spongy brake pedal?", "Air in the brake lines, old or low fluid, a leak, or worn components. Have it inspected promptly."),
 ("What is the difference between DOT 3 and DOT 4 brake fluid?", "They have different boiling points. Use the type on the reservoir cap or in the manual, and never mix glycol-based fluids with DOT 5 silicone fluid."),
]),
"brake_noises": ("Brake noises and symptoms", [
 ("Why do my brakes squeal?", "Common causes are the wear indicator on worn pads, glazed pads, or dust and moisture. If it continues, have the brakes inspected."),
 ("What does a grinding noise when braking mean?", "Usually the pads are worn through and metal is touching metal. Stop driving the car if you can and have it inspected."),
 ("Why does the brake pedal pulsate when I brake?", "Typically warped or unevenly worn brake discs, which cause a vibration you feel through the pedal."),
 ("Why does my car pull to one side when braking?", "Possible causes are a stuck caliper, uneven pad wear or different tyre pressures. Have it checked because it affects safety."),
]),
"air_filter": ("Engine air filter", [
 ("What does the engine air filter do?", "It stops dust and debris from entering the engine so that the air used for combustion is clean."),
 ("How often should the engine air filter be replaced?", "Commonly every 15,000-30,000 km, and sooner on dusty roads. Follow the manual."),
 ("What are symptoms of a clogged air filter?", "Reduced power, poorer fuel economy, sluggish acceleration or a rough idle."),
 ("Can I wash and reuse a paper air filter?", "Generally no. Paper elements are meant to be replaced. Tapping out loose dust helps only briefly."),
]),
"cabin_filter": ("Cabin air filter", [
 ("What does the cabin air filter do?", "It filters dust, pollen and pollutants out of the air that enters the cabin through the AC and vents."),
 ("What are symptoms of a clogged cabin filter?", "Weak airflow from the vents, a musty smell, or windows that fog up more easily."),
 ("How often should the cabin filter be changed?", "Roughly every 10,000-20,000 km or once a year, sooner in dusty or polluted areas."),
 ("Where is the cabin filter located?", "Usually behind the glovebox or under the dash or bonnet scuttle. The owner's manual shows the exact location."),
]),
"spark_plugs": ("Spark plugs", [
 ("What do spark plugs do?", "They ignite the air-fuel mixture in each cylinder of a petrol engine."),
 ("How often should spark plugs be replaced?", "Copper plugs often need replacing sooner, around 30,000-50,000 km, while iridium or platinum plugs can last 60,000-100,000 km or more. Follow the manual."),
 ("What are signs of worn spark plugs?", "Misfires, rough idle, hard starting, hesitation and worse fuel economy."),
 ("Do diesel engines have spark plugs?", "No. Diesels use compression ignition. They have glow plugs to help cold starts."),
]),
"timing_belt": ("Timing belt and chain", [
 ("What does a timing belt do?", "It keeps the crankshaft and camshaft(s) synchronised so the valves open and close at the right time."),
 ("When should a timing belt be replaced?", "Commonly every 60,000-100,000 km or as the manual says. Some engines use a timing chain instead."),
 ("What happens if the timing belt breaks?", "The engine stops immediately. In an interference engine the pistons can hit the valves, causing severe and costly damage."),
 ("What is the difference between a timing belt and a timing chain?", "A chain is metal and often lasts longer but can still stretch, while a rubber belt needs scheduled replacement."),
]),
"transmission_fluid": ("Transmission fluid", [
 ("Why is transmission fluid important?", "It lubricates and cools the gearbox, and in an automatic it also helps transmit hydraulic pressure for shifting."),
 ("How often should transmission fluid be changed?", "It varies widely. Manuals may say 40,000-100,000 km or even call it lifetime fluid, and severe use calls for earlier changes."),
 ("What are signs of transmission problems?", "Slipping gears, delayed or harsh shifts, a burnt smell, or dark fluid."),
 ("How do I check transmission fluid?", "Some cars have a dipstick, but many have sealed transmissions that a workshop must check. Follow the manual."),
]),
"clutch": ("Manual clutch", [
 ("What are signs of a worn clutch?", "Slipping (revs rise without matching acceleration), a high biting point, a burning smell and difficulty changing gear."),
 ("How can I make my clutch last longer?", "Do not rest your foot on the pedal, avoid riding the clutch on slopes (use the handbrake), and change gear smoothly."),
 ("Why is my clutch pedal spongy?", "Air or low fluid in the hydraulic system, or a leak. Have the system checked."),
 ("Why is it hard to shift into gear?", "The clutch may not be fully disengaging because of low fluid, wear or a linkage problem."),
]),
"wipers_washer": ("Wipers and washer fluid", [
 ("When should I replace wiper blades?", "Typically every 6-12 months, or when they streak, chatter or skip across the glass."),
 ("Why do my wipers leave streaks?", "Worn or dirty blades, or a dirty windscreen. Clean the glass and blades, and replace the blades if it continues."),
 ("Can I use plain water in the washer reservoir?", "In an emergency, yes. Proper washer fluid cleans better and resists freezing."),
 ("Is it okay to run the wipers on a dry windscreen?", "Avoid it. Dry wiping can scratch the glass and wear the blades. Spray washer fluid first."),
]),
"headlights": ("Headlights and bulbs", [
 ("Why are my headlights dim?", "Causes include aging bulbs, yellowed or foggy lenses, a weak battery or alternator, or a poor electrical connection."),
 ("Should I replace headlight bulbs in pairs?", "It is recommended, since both bulbs have aged equally and will be similar in brightness."),
 ("How can I fix foggy headlight lenses?", "Use a polishing kit or have them professionally restored, then apply a UV sealant so they do not yellow again."),
 ("Why should I not touch a halogen bulb's glass?", "Skin oils can create hot spots on the glass and make the bulb fail early. Hold it by the base or use gloves."),
]),
"check_engine_light": ("Check engine light", [
 ("What does the check engine light mean?", "The engine control unit has detected a fault in the engine or emissions system. A scan tool is needed to read the stored code."),
 ("What is the difference between a steady and a flashing check engine light?", "A steady light means get it checked soon. A flashing light usually signals a serious misfire that can damage the catalytic converter, so reduce load and stop driving as soon as it is safe."),
 ("What are common causes of the check engine light?", "A loose or faulty fuel cap, a bad oxygen sensor, worn spark plugs or coils, a dirty mass airflow sensor, or a failing catalytic converter."),
 ("How do I read a check engine code?", "Plug an OBD-II scanner into the diagnostic port under the dash. A code such as P0300 points to the system involved, not the exact part to replace."),
]),
"warning_lights": ("Dashboard warning lights", [
 ("What do the colours of warning lights mean?", "Red means a serious problem, so stop safely. Amber or yellow means caution and a check soon. Green or blue usually means a system is on."),
 ("What should I do if the red oil pressure light comes on?", "Stop and switch off the engine as soon as it is safe, then check the oil level. Do not keep driving, as it can destroy the engine."),
 ("What does the battery warning light mean?", "A fault in the charging system, such as the alternator, drive belt or battery connection. Drive only to a nearby safe place."),
 ("Why is my brake warning light on?", "It could be the parking brake still on, low brake fluid or a fault. If it stays on after releasing the handbrake, have the brakes checked before driving."),
]),
"fuel_economy": ("Improving fuel economy", [
 ("How can I improve my car's mileage?", "Keep tyres at the right pressure, accelerate smoothly, avoid long idling, remove unnecessary weight and keep up with servicing."),
 ("Does using the AC reduce fuel economy?", "Yes, the compressor adds engine load. At low speeds windows down can use less fuel, while at highway speeds open windows add drag."),
 ("How does speed affect fuel consumption?", "Consumption generally rises at higher speeds because of aerodynamic drag, so steady moderate speeds are most efficient."),
 ("Can a dirty air filter or wrong oil hurt fuel economy?", "They can reduce it slightly. A clogged filter restricts airflow, and the wrong oil grade can increase friction."),
]),
"fuel_system": ("Fuel filter and fuel quality", [
 ("What does the fuel filter do?", "It traps dirt and rust particles before they reach the injectors."),
 ("What are signs of a clogged fuel filter?", "Hesitation under load, hard starting, stalling or loss of power."),
 ("What are signs of bad fuel?", "Knocking, rough running soon after refuelling and poor mileage."),
 ("Is it bad to run the tank very low?", "It is best avoided. Sediment collects at the bottom of the tank, and the fuel pump uses fuel to help keep itself cool."),
]),
"suspension": ("Suspension and shock absorbers", [
 ("What are signs of worn shock absorbers?", "A bouncy ride, nose-dive when braking, body roll in corners, uneven tyre wear or oil leaking from the shock."),
 ("How can I do a quick bounce test?", "Push down hard on one corner of the car and release. If it bounces more than once or twice, the shock may be worn."),
 ("Should shock absorbers be replaced in pairs?", "Yes, replace them in pairs on the same axle so handling stays balanced."),
 ("What causes clunking over bumps?", "Worn bushings, ball joints, anti-roll bar links or strut mounts."),
]),
"steering": ("Steering", [
 ("Why is my steering heavy?", "Possible causes are low power steering fluid, a failing pump (hydraulic systems), a fault in electric assist, or low tyre pressure."),
 ("Why does my car whine when I turn the steering wheel?", "Often low power steering fluid or a worn pump in a hydraulic system."),
 ("Do all cars use power steering fluid?", "No. Many modern cars use electric power steering, which has no fluid."),
 ("Why does the steering wheel shake at high speed?", "Commonly wheel imbalance, a bent rim or worn suspension or steering parts."),
]),
"ac_system": ("Air conditioning", [
 ("Why is my AC not cooling well?", "Causes include low refrigerant from a leak, a clogged cabin filter, a failing compressor, a blocked condenser or a faulty fan."),
 ("Why does my AC smell musty?", "Mould or bacteria can grow on the evaporator. Replacing the cabin filter and using an AC cleaner can help, and running the fan with AC off before parking helps dry it out."),
 ("How often does a car AC need regassing?", "It is not a routine job. A sealed system should not lose refrigerant, so needing a top-up suggests a leak."),
 ("Why does the AC compressor not engage?", "Causes include low refrigerant pressure, a blown fuse or relay, or an electrical fault."),
]),
"drive_belt": ("Serpentine / drive belt", [
 ("What does the serpentine belt drive?", "Typically the alternator, the AC compressor and, depending on the car, the power steering pump and water pump."),
 ("What are signs of a worn drive belt?", "Squealing, visible cracks, fraying or glazing, and loss of AC, power steering or charging."),
 ("How often should the drive belt be checked or replaced?", "Inspect it regularly and replace it per the manual, commonly in the range of 60,000-100,000 km."),
 ("What happens if the serpentine belt breaks?", "You can lose charging, power steering assist and possibly cooling, so stop safely to avoid overheating."),
]),
"exhaust_emissions": ("Exhaust and emissions", [
 ("What does a catalytic converter do?", "It converts harmful exhaust gases into less harmful ones such as carbon dioxide and water."),
 ("What are signs of a failing catalytic converter?", "A check engine light, a rotten-egg smell, reduced power or a rattling noise."),
 ("Why is my exhaust suddenly loud?", "There is likely a leak or hole in the muffler, pipe or joint."),
 ("What does the oxygen sensor do?", "It measures oxygen in the exhaust so the engine computer can adjust the fuel mixture. A bad sensor hurts mileage and emissions."),
]),
"diesel": ("Diesel-specific care", [
 ("What is a glow plug?", "A heater in a diesel engine's combustion chamber that helps it start when cold."),
 ("What is a diesel particulate filter (DPF)?", "A filter that traps soot from the exhaust and periodically burns it off. Frequent short trips can clog it, and a longer highway drive helps it regenerate."),
 ("What should I do if I put petrol in a diesel car?", "Do not start the engine. Petrol can damage the fuel pump and injectors, so have the tank drained by a workshop."),
 ("Why drain the water separator in a diesel car?", "If your car has one, water in the fuel can damage the injection system, so drain it as the manual says."),
]),
"hybrid_ev": ("Hybrid and EV basics", [
 ("Do hybrid cars still need oil changes?", "Yes, because they have a petrol engine, although the schedule may differ from a conventional car."),
 ("How is EV maintenance different?", "There is no engine oil, spark plugs or timing belt. You still maintain tyres, brakes, coolant, the cabin filter and the 12V battery."),
 ("Why does an EV have a 12V battery?", "It powers accessories and control systems. If it fails, the car may not start up even if the main battery is charged."),
 ("Why should I never touch orange cables in a hybrid or EV?", "Orange marks high-voltage wiring that can cause fatal shocks. Only trained technicians should work on it."),
]),
"monsoon_care": ("Monsoon driving care", [
 ("Should I drive through a flooded road?", "Avoid deep or unknown water. If it reaches the bottom of the doors or you cannot judge the depth, turn back. Water entering the engine intake can wreck the engine."),
 ("What should I do if my car stalls in water?", "Do not try to restart it. Push it to a dry place and have it inspected, since restarting can cause serious engine damage."),
 ("How do I dry the brakes after driving through water?", "Drive slowly and press the brake pedal lightly a few times to dry the pads and discs."),
 ("How do I stop the windows fogging in the rain?", "Use the AC with the demist setting, clean the inside of the glass and make sure the wipers are in good condition."),
]),
"long_term_storage": ("Storing a car", [
 ("How do I prepare a car for storage of a few months?", "Wash it, change the oil, fill the tank (with fuel stabiliser for petrol), inflate the tyres slightly more, cover it and use a battery maintainer or disconnect the battery."),
 ("How do I avoid flat spots on tyres during storage?", "Move the car periodically or raise the pressure slightly, and avoid parking in the same position for months."),
 ("Should I leave the handbrake on when storing a car?", "Avoid leaving the parking brake engaged for a long time, since pads can stick. Use wheel chocks instead."),
 ("Should I start a stored car regularly?", "If you do, run it long enough to reach normal temperature. Very short idling can leave moisture in the engine and exhaust."),
]),
"washing_paint": ("Washing and paint care", [
 ("How often should I wash my car?", "Roughly every 2-4 weeks, and sooner after bird droppings, tree sap or road salt, which can damage paint."),
 ("Can I use dish soap to wash my car?", "It is not recommended because it can strip wax and protective coatings. Use a proper car shampoo."),
 ("How can I avoid swirl marks when washing?", "Rinse first, use the two-bucket method and soft microfibre mitts and towels, and avoid washing in direct sun."),
 ("How often should I wax my car?", "Wax roughly every 3 months. Paint sealants and ceramic coatings usually last longer."),
]),
"rust": ("Rust prevention", [
 ("What causes car rust?", "Moisture and oxygen reacting with exposed steel, made worse by road salt and by chips or scratches in the paint."),
 ("How can I prevent rust?", "Wash the car including the underbody, touch up paint chips quickly, keep door and sill drain holes clear and keep the paint waxed."),
 ("How do I treat small surface rust spots?", "Sand the area, apply a rust converter, prime and repaint. Extensive rust needs professional repair."),
 ("Where does rust usually appear first?", "Wheel arches, door bottoms, sills and the underbody."),
]),
"service_schedule": ("Service schedule", [
 ("Where do I find my car's service schedule?", "In the owner's manual or the service booklet."),
 ("Which comes first, the time or distance interval?", "Whichever comes first. A car driven little still needs time-based service."),
 ("What happens if I skip scheduled services?", "Wear can go unnoticed and breakdowns become more likely, and it can affect your warranty."),
 ("Why should I keep service records?", "They support warranty claims and help resale value by showing the car has been maintained."),
]),
"pre_trip": ("Pre-trip checks", [
 ("What should I check before a long trip?", "Tyre pressure including the spare, oil and coolant levels, washer fluid, lights, brakes, wipers and the battery."),
 ("What should I carry in the car for emergencies?", "A spare tyre, jack and wrench, a warning triangle, a first-aid kit, a torch, jumper cables and your documents."),
 ("How often should I stop on a long drive?", "Roughly every two hours to rest, since driver fatigue is a major risk."),
 ("What should the dashboard lights do when I start the car?", "Most warning lights come on briefly during the self-check and go off once the engine is running. Any that stay on need attention."),
]),
"rough_idle": ("Misfire and rough idle", [
 ("What is an engine misfire?", "One or more cylinders are not burning the fuel properly. Causes include spark plugs, ignition coils, injectors, vacuum leaks or low compression."),
 ("What causes a rough idle?", "A dirty throttle body, a vacuum leak, faulty sensors, worn spark plugs or dirty injectors."),
 ("Why does the engine hesitate when I accelerate?", "Possibly a clogged fuel filter, worn spark plugs, a dirty mass airflow sensor or a fuel delivery issue."),
 ("Is it normal for the idle to dip when the AC turns on?", "A slight dip is normal. A large drop or stalling suggests a problem with idle control or the engine."),
]),
"no_start": ("Hard starting and stalling", [
 ("Why does my car crank but not start?", "It is missing fuel, spark or air. Possible causes include a failed fuel pump, a crankshaft sensor fault or an immobiliser issue."),
 ("What does a clicking sound when I turn the key mean?", "Usually a weak battery, poor battery connections or a failing starter solenoid."),
 ("Why does my car stall at idle?", "Possible causes are a dirty throttle body or idle control valve, a vacuum leak or a fuel delivery problem."),
 ("Why is my car hard to start in cold weather?", "A weak battery, worn spark plugs, thick oil, or in diesels faulty glow plugs."),
]),
"exhaust_smoke": ("Exhaust smoke colours", [
 ("What does blue smoke from the exhaust mean?", "The engine is burning oil, often from worn piston rings or valve seals."),
 ("What does thick white smoke mean?", "Coolant may be burning, possibly from a head gasket leak. Thin white vapour on a cold start is normal condensation."),
 ("What does black smoke mean?", "The engine is burning too much fuel, which can be caused by a clogged air filter or faulty injectors."),
 ("Is water dripping from the exhaust normal?", "Yes. Water vapour is a combustion by-product and condenses in the exhaust."),
]),
"noises": ("Vibrations and noises", [
 ("Why does my car vibrate at highway speed?", "Commonly unbalanced wheels, a bent rim or tyre problems."),
 ("What causes a humming noise that rises with speed?", "Often a worn wheel bearing or uneven tyre wear."),
 ("Why do I hear clicking when turning?", "Often a worn CV joint, which should be repaired before it fails."),
 ("What does an engine knocking sound mean?", "Possible causes include low oil, poor fuel quality, carbon build-up or internal wear. Stop and check the oil level, and have it diagnosed."),
]),
"fluid_leaks": ("Fluid leaks", [
 ("What do different fluid colours under the car mean?", "Dark brown or black is usually engine oil. Green, orange or pink is often coolant. Red or pink can be transmission or power steering fluid. Clear water is usually AC condensation."),
 ("Is a brake fluid leak dangerous?", "Yes. Brake fluid loss can cause brake failure, so do not drive the car until it is repaired."),
 ("Is water under my car after using the AC normal?", "Yes, the AC removes moisture from the cabin air and drains it under the car."),
 ("How can I find where a leak is coming from?", "Place a sheet of cardboard under the car overnight and note the position and colour of the drips."),
]),
"flat_tyre": ("Changing a flat tyre", [
 ("How do I change a flat tyre safely?", "Park on level ground away from traffic, use hazard lights and the handbrake, loosen the wheel nuts slightly before lifting, jack at the designated points, swap the wheel and tighten the nuts in a star pattern."),
 ("How fast can I drive on a space-saver spare?", "Temporary spares are speed-limited, often to about 80 km/h. Check the label on the wheel and replace it with a full tyre soon."),
 ("Should I re-check the wheel nuts after changing a tyre?", "Yes, re-check the tightness after roughly 50-100 km."),
 ("Is it safe to get under a car held only by a jack?", "No. Never go under a car supported only by a jack, as it can slip. Use jack stands for any work underneath."),
]),
"fuses": ("Fuses and electrical", [
 ("What should I use to replace a blown fuse?", "Only a fuse with the same amp rating. A higher rating can overheat wiring and cause a fire."),
 ("Where is the fuse box in a car?", "Typically in the engine bay and under the dashboard or in the footwell. The manual has a diagram."),
 ("Why does a fuse keep blowing?", "It usually indicates a short circuit or overloaded circuit, so find the cause instead of just replacing the fuse."),
 ("My 12V accessory socket stopped working. What should I check?", "Check the fuse for that circuit first, then the socket itself for debris or damage."),
]),
"alternator": ("Alternator and charging", [
 ("What does the alternator do?", "It generates electricity to run the car's systems and recharge the battery while the engine is running."),
 ("What are signs of a failing alternator?", "The battery warning light, dimming lights, a whining noise, or a battery that keeps going flat."),
 ("How can I test the charging system?", "With a multimeter on the battery terminals and the engine running, you should typically see around 13.5-14.5 volts."),
 ("What voltage should a healthy battery show with the engine off?", "A fully charged 12V battery usually reads around 12.6 volts when rested."),
]),
"cv_joint": ("CV joints and drive axles", [
 ("What are the signs of a failing CV joint?", "Clicking or popping when turning, grease flung around the wheel area, and vibration under acceleration."),
 ("What does a torn CV boot mean?", "The grease can escape and dirt can get in. Replacing the boot early may save the joint, but a damaged joint needs replacement."),
 ("Is it safe to drive with a clicking CV joint?", "Not for long. It can fail completely and leave the car unable to move, so repair it soon."),
 ("What causes CV boots to tear?", "Age, heat, road debris and wear, which make the rubber crack."),
]),
"diy_vs_garage": ("DIY vs workshop", [
 ("Which maintenance jobs are suitable for beginners?", "Checking tyre pressure, topping up fluids, replacing wiper blades, air and cabin filters and some bulbs."),
 ("Which jobs should I leave to a professional?", "Brake work if you lack experience, airbags, timing belts, fuel system repairs and any high-voltage hybrid or EV work."),
 ("Will servicing at an independent garage void my warranty?", "It depends on the terms. Keep records and use correct parts and fluids, and check your warranty documents."),
 ("What should I ask for when getting a repair quote?", "An itemised quote covering parts and labour, and ask to see or keep the replaced parts."),
]),
}
